const messages = {}
// Troisième valeur facultative : le malgache (à relire par un locuteur) ; à défaut, le français s'affiche.
const entree = ([fr, en, mg]) => (mg ? { fr, en, mg } : { fr, en })
for (const [cle, v] of Object.entries(LIBELLES)) messages[cle] = entree(v)
for (const [s, v] of Object.entries(STATUTS)) messages[`clm.statut.${s}`] = entree(v)
for (const [e, v] of Object.entries(EVENEMENTS)) messages[`clm.evt.${e}`] = entree(v)

/** Types d'événements du journal scellé (filtre « action » du journal d'audit, UI-23). */
export const TYPES_EVENEMENTS = Object.keys(EVENEMENTS)

export default messages
